import React, { useEffect, useState } from 'react';
import { 
  Card, 
  CardContent, 
  CardMedia, 
  Typography, 
  Container,
  Chip,
  Box
} from '@mui/material';
import HomeHeaderNavi from './components/Nav/seriespageheader';
import Grid from '@mui/material/Grid';

interface BlogPost {
  id: number;
  title: string;
  date: string;
  thumbnail: string;
  excerpt: string;
  category: string;
}

const SerializedManga: React.FC = () => {
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    setIsLoading(true);
    fetch('/serializedmanga.json')
      .then(response => response.json())
      .then(data => {
        setPosts(data.posts);
        setIsLoading(false);
      })
      .catch(error => {
        console.error('Error loading blog posts:', error);
        setError(error.message);
        setIsLoading(false);
      });
  }, []);

  if (isLoading) {
    return (
      <Container>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  if (error) {
    return (
      <Container>
        <Typography color="error">Error: {error}</Typography>
      </Container>
    );
  }

  return (
    <>
      <HomeHeaderNavi />
      <Container>
        <Typography variant="h4" component="h1" gutterBottom sx={{ 
          textAlign: 'center', 
          my: 4,
          fontWeight: 'bold'
        }}>
          現在連載中の作品一覧
        </Typography>

        <Grid container spacing={4}>
          {posts.map((post,i) => (
              <Card 
                sx={{ 
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  transition: 'all 0.3s ease-in-out',
                  borderRadius: '16px',
                  background: 'linear-gradient(145deg, #ffffff, #f6f7f9)',
                  boxShadow: '8px 8px 16px #e3e3e3, -8px -8px 16px #ffffff',
                  border: 'none',
                  '&:hover': {
                    transform: 'translateY(-12px) scale(1.02)',
                    boxShadow: '12px 12px 20px #d1d1d1, -12px -12px 20px #ffffff',
                  }
                }}
              >
                <CardMedia
                  component="img"
                  height="220"
                  image={post.thumbnail}
                  alt={post.title}
                  sx={{ 
                    objectFit: 'cover',
                    borderTopLeftRadius: '16px',
                    borderTopRightRadius: '16px',
                    transition: 'transform 0.3s ease',
                    '&:hover': {
                      transform: 'scale(1.05)'
                    }
                  }}
                />
                <CardContent sx={{ 
                  flexGrow: 1,
                  p: 3,
                  '&:last-child': { pb: 3 }
                }}>
                  <Box sx={{ mb: 2 }}>
                    <Typography
                      variant="caption"
                      color="text.secondary"
                      component="p"
                      sx={{ 
                        ml: 1, 
                        display: 'inline-block',
                        fontSize: '0.85rem',
                        fontWeight: 500
                      }}
                    >
                      {post.date}
                    </Typography>
                  </Box>
                  <Typography 
                    gutterBottom 
                    variant="h6" 
                    component="h2"
                    sx={{ 
                      fontWeight: 700,
                      mb: 2,
                      lineHeight: 1.4,
                      fontSize: '1.25rem',
                      color: '#1a1a1a',
                      transition: 'color 0.2s ease',
                      '&:hover': {
                        color: '#009879'
                      }
                    }}
                  >
                    {post.title}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    color="text.secondary"
                    sx={{
                      lineHeight: 1.6,
                      color: '#666666',
                      fontSize: '0.95rem'
                    }}
                  >
                    {post.excerpt}
                  </Typography>
                </CardContent>
              </Card>

          ))}
        </Grid>
      </Container>
    </>
  );
};

export default SerializedManga;
